<?php $sent=false;$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['_csrf']??null)){$error='Security token expired. Refresh and try again.';}else{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message===''){$error='Please provide a valid name, email and message.';}else{try{$stmt=db()->prepare('INSERT INTO messages(name,email,subject,message) VALUES(:name,:email,:subject,:message)');$stmt->execute([':name'=>$name,':email'=>$email,':subject'=>$subject,':message'=>$message]);$sent=true;}catch(Throwable $e){$error='The contact service is temporarily unavailable. Please try again later.';}}}} ?><main><section class="section"><div class="section__heading"><span>01</span><h2>Contact</h2></div><div class="glass-panel"><p class="hero__lead">Have a product, system or idea worth building? Send a message.</p><?php if($sent): ?><p>Message received. Thank you.</p><?php elseif($error): ?><p><?=e($error)?></p><?php endif; ?><form method="post" class="contact-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input name="name" placeholder="Your name" required><input type="email" name="email" placeholder="Email address" required><input name="subject" placeholder="Subject"><textarea name="message" rows="7" placeholder="Tell me what you are building..." required></textarea><button class="button button--primary" type="submit">Send message</button></form></div></section></main>